using FlexExtractor;
static partial class Cases {
 public static void TestReviewPurgeNullManifestFieldsDoNotEscapeIsolation(){foreach(var record in new[]{"{\"Name\":null,\"Hash\":null}","{\"Name\":\"Request_a.xml\",\"Hash\":null}"}){var(c,dest)=ExpiredOwned();var bad=Path.Combine(Path.GetDirectoryName(c.WatchRoot)!,"out-bad");Directory.CreateDirectory(bad);File.WriteAllText(Path.Combine(bad,Ownership.Manifest),"{\"Files\":["+record+"]}");c.DispenseItems.Insert(0,new(){Token="31",StationName="bad",SaveFolder=bad});var r=(ScanResult)Scan(c,"purge");Program.Check(r.Failed==1&&r.Deleted==1&&!File.Exists(dest),"malformed manifest escaped per-target isolation");}}
 public static void TestReviewPurgeCorruptFirstTargetDoesNotStarveHealthy(){var(c,first)=ExpiredOwned();var second=Path.Combine(Path.GetDirectoryName(c.WatchRoot)!,"out-second");c.BindItems=[new(){Token="31",StationName="second",SaveFolder=second}];c.KeepDays=14;Scan(c);var healthy=Directory.GetFiles(second,"Request*.xml").Single();var corrupt=Path.Combine(c.DispenseItems[0].SaveFolder,Ownership.Manifest);File.WriteAllText(corrupt,"{broken");c.KeepDays=1;for(int i=0;i<3;i++){var r=(ScanResult)Scan(c,"purge");Program.Check(r.Failed==1&&r.Messages.Count==1,"corrupt target not individually reported");if(i==0)Program.Check(r.Deleted==1&&!File.Exists(healthy),"healthy expired output starved by corrupt first target");Program.Check(File.Exists(first)&&File.ReadAllText(corrupt)=="{broken","bad target did not fail closed");}Program.Check(Ownership.Load(second).Files.Count==0,"healthy manifest not updated");}
 public static void TestReviewPurgeReparseFirstTargetIsolated(){var(c,dest)=ExpiredOwned();var healthy=c.DispenseItems[0].SaveFolder;var alias=Path.Combine(Path.GetDirectoryName(c.WatchRoot)!,"bad-output-alias");Junction(alias,healthy);try{c.DispenseItems.Insert(0,new(){Token="31",StationName="bad",SaveFolder=alias});var r=(ScanResult)Scan(c,"purge");Program.Check(r.Failed==1&&r.Deleted==1&&!File.Exists(dest),"unsafe target blocked healthy target purge");}finally{Directory.Delete(alias);}}
}
